<?php
namespace App\Services\Automation\Handlers;
use App\Models\AutomationRun; use App\Models\OzonAccount; use App\Models\OzonTaxonomyNode; use App\Services\Automation\AutomationHandlerInterface; use App\Services\Automation\AutomationProgressReporterInterface; use App\Services\Ozon\OzonTaxonomyService;
class OzonTaxonomySyncHandler implements AutomationHandlerInterface { public function __construct(private readonly OzonTaxonomyService $service) {} public function handle(AutomationRun $run, AutomationProgressReporterInterface $progress, bool $dryRun=false): array { $progress->start(1,'Загрузка taxonomy Ozon.'); $nodeId=(int)($run->context['ozon_taxonomy_node_id'] ?? 0); $result=$nodeId ? $this->service->syncAttributes(OzonTaxonomyNode::query()->findOrFail($nodeId),$run) : $this->service->syncTree(OzonAccount::query()->findOrFail((int)($run->context['ozon_account_id'] ?? 0)),$run); $processed=(int)$result['processed_items']; $progress->setProgress($processed,$processed,'Taxonomy Ozon загружена.'); return [...$result,'total_items'=>$processed,'message'=>'Taxonomy Ozon загружена.']; } }
